func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, nil, a.Binary(), "--force", "--workspace", dir)
	if err != nil {
		return nil, err
	}

	// The Cursor CLI shows a workspace trust dialog in interactive mode
	// (--trust only works in headless/--print mode). Wait for the dialog
	// and press "a" to trust the workspace.
	if _, err := s.WaitFor(`Trust this workspace`, 30*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for trust dialog: %w", err)
	}
	if err := s.SendKeys("a"); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("accepting trust dialog: %w", err)
	}

	// Wait for the TUI to be ready (input prompt).
	if _, err := s.WaitFor(`>`, 30*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

