input.new_string:
	// Fire EventSessionStart for the current session (if state exists).
	// If no state exists, initialize the session so that agents that skip
	// TurnStart in headless mode (e.g., Cursor CLI with -p) still create
	// a session state file for prepare-commit-msg to find.
	if state, loadErr := strategy.LoadSessionState(ctx, event.SessionID); loadErr != nil {
		logging.Warn(logCtx, "failed to load session state on start",
			slog.String("error", loadErr.Error()))
	} else if state != nil {
		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			logging.Warn(logCtx, "session start transition failed",
				slog.String("error", transErr.Error()))
		}
		if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
			logging.Warn(logCtx, "failed to update session state on start",
				slog.String("error", saveErr.Error()))
		}
	} else {
		// No existing state — initialize the session. This is needed for
		// headless agents (e.g., Cursor CLI -p mode) where TurnStart never
		// fires but the agent still commits during the session.
		if err := strategy.EnsureSetup(ctx); err != nil {
			logging.Warn(logCtx, "failed to ensure strategy setup on session start",
				slog.String("error", err.Error()))
		}
		if err := strat.InitializeSession(ctx, event.SessionID, ag.Type(), event.SessionRef, event.Prompt); err != nil {
			logging.Warn(logCtx, "failed to initialize session on session start",
				slog.String("error", err.Error()))
		}
	}

	return nil
}

