    24→// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
    25→// The CLI binary is called "agent" and uses Cursor's hooks system via
    26→// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
    27→//
    28→// Key limitation: in headless (-p) mode, the beforeSubmitPrompt and stop hooks
    29→// do NOT fire. Only sessionStart, sessionEnd, and tool-use hooks fire. This
    30→// means RunPrompt-based tests won't get TurnStart/TurnEnd events. Interactive
    31→// tmux-based tests get the full lifecycle.
    32→type CursorCLI struct{}
    33→
    34→func (a *CursorCLI) Name() string               { return "cursor-cli" }
    35→func (a *CursorCLI) Binary() string             { return "agent" }
    36→func (a *CursorCLI) EntireAgent() string        { return "cursor" }
    37→func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }
    38→
    39→// PromptPattern returns a regex matching the Cursor CLI's TUI input prompt.
    40→// The CLI shows a styled input box with placeholder text when ready for input.
    41→func (a *CursorCLI) PromptPattern() string { return `/ commands` }
    42→
    43→func (a *CursorCLI) IsTransientError(out Output, err error) bool {
    44→	if err == nil {
    45→		return false
    46→	}
    47→	if errors.Is(err, context.DeadlineExceeded) {
    48→		return true
    49→	}
    50→	combined := out.Stdout + out.Stderr
    51→	for _, p := range []string{
    52→		"overloaded",
    53→		"rate limit",
    54→		"429",
    55→		"503",
    56→		"529",
    57→		"ECONNRESET",
    58→		"ETIMEDOUT",
    59→		"server error",
    60→		"Internal Server Error",
    61→	} {
    62→		if strings.Contains(combined, p) {
    63→			return true
    64→		}
    65→	}
    66→	return false
    67→}
