    69→func (a *CursorCLI) Bootstrap() error {
    70→	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
    71→	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
    72→	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
    73→		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
    74→	}
    75→	return nil
    76→}
