   138→func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
   139→	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
   140→	s, err := NewTmuxSession(name, dir, nil, a.Binary(), "--force", "--workspace", dir)
   141→	if err != nil {
   142→		return nil, err
   143→	}
   144→
   145→	// The Cursor CLI shows a workspace trust dialog in interactive mode
   146→	// (--trust only works in headless/--print mode). Wait for the dialog
   147→	// and press "a" to trust the workspace.
   148→	if _, err := s.WaitFor(`Trust this workspace`, 30*time.Second); err != nil {
   149→		_ = s.Close()
   150→		return nil, fmt.Errorf("waiting for trust dialog: %w", err)
   151→	}
   152→	if err := s.SendKeys("a"); err != nil {
   153→		_ = s.Close()
   154→		return nil, fmt.Errorf("accepting trust dialog: %w", err)
   155→	}
   156→
   157→	// Wait for the TUI to be ready (input prompt).
   158→	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
   159→		_ = s.Close()
   160→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
   161→	}
   162→	s.stableAtSend = ""
   163→
   164→	return s, nil
   165→}
