func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
		return
	}
	// Resolve the absolute path to the agent binary so tmux sessions on CI
	// can find it even if PATH isn't propagated to tmux's login shell.
	binPath, err := exec.LookPath("agent")
	if err != nil {
		return
	}
	Register(&CursorCLI{binPath: binPath})
}

